/**
 * Fixed Glue Python shell script that applies the SQL files listed in
 * sql/apply-plan.json through the Redshift Data API or Athena.
 */
export function sqlApplyScript(): string {
  return [
    "# Generated by aws-data-modernizer. Applies the SQL files listed in sql/apply-plan.json.",
    "import json",
    "import sys",
    "import time",
    "",
    "import boto3",
    "",
    "",
    "def raw_args():",
    "    values = {}",
    "    index = 1",
    "    while index < len(sys.argv):",
    "        item = sys.argv[index]",
    "        if item.startswith('--'):",
    "            key, separator, value = item[2:].partition('=')",
    "            if separator:",
    "                values[key] = value",
    "            elif index + 1 < len(sys.argv) and not sys.argv[index + 1].startswith('--'):",
    "                values[key] = sys.argv[index + 1]",
    "                index += 1",
    "            else:",
    "                values[key] = ''",
    "        index += 1",
    "    return values",
    "",
    "",
    "RAW = raw_args()",
    "",
    "for required in ('phase', 'scripts_bucket', 'target'):",
    "    if not RAW.get(required):",
    "        raise ValueError(f'Missing required --{required} argument')",
    "",
    "PHASE = RAW['phase']",
    "SCRIPTS_BUCKET = RAW['scripts_bucket']",
    "TARGET = RAW['target']",
    "PLAN_KEY = RAW.get('plan_key') or 'sql/apply-plan.json'",
    "WORKGROUP = RAW.get('workgroup')",
    "DATABASE = RAW.get('database')",
    "ATHENA_WORKGROUP = RAW.get('athena_workgroup')",
    "LAKE_BUCKET = RAW.get('lake_bucket')",
    "STAGING_BUCKET = RAW.get('staging_bucket')",
    "",
    "",
    "def fetch_text(bucket, key):",
    "    body = boto3.client('s3').get_object(Bucket=bucket, Key=key)['Body']",
    "    return body.read().decode('utf-8')",
    "",
    "",
    "def split_statements(text):",
    "    statements = []",
    "    buffer = []",
    "    in_quote = False",
    "    i = 0",
    "    while i < len(text):",
    "        ch = text[i]",
    "        if in_quote:",
    "            buffer.append(ch)",
    '            if ch == "\'":',
    '                if i + 1 < len(text) and text[i + 1] == "\'":',
    '                    buffer.append("\'")',
    "                    i += 2",
    "                    continue",
    "                in_quote = False",
    "            i += 1",
    "            continue",
    '        if ch == "\'":',
    "            in_quote = True",
    "            buffer.append(ch)",
    "            i += 1",
    "            continue",
    "        if ch == '-' and text[i:i + 2] == '--':",
    "            end = text.find('\\n', i)",
    "            if end < 0:",
    "                end = len(text)",
    "            i = end",
    "            continue",
    "        if ch == ';':",
    "            statement = ''.join(buffer).strip()",
    "            if statement:",
    "                statements.append(statement)",
    "            buffer = []",
    "            i += 1",
    "            continue",
    "        buffer.append(ch)",
    "        i += 1",
    "    statement = ''.join(buffer).strip()",
    "    if statement:",
    "        statements.append(statement)",
    "    return statements",
    "",
    "",
    "def apply_redshift(sql):",
    "    client = boto3.client('redshift-data')",
    "    result = client.execute_statement(",
    "        WorkgroupName=WORKGROUP,",
    "        Database=DATABASE,",
    "        Sql=sql,",
    "    )",
    "    statement_id = result['Id']",
    "    while True:",
    "        desc = client.describe_statement(Id=statement_id)",
    "        status = desc.get('Status')",
    "        if status in ('FINISHED', 'FAILED', 'ABORTED'):",
    "            break",
    "        time.sleep(2)",
    "    if status != 'FINISHED':",
    "        raise RuntimeError(desc.get('Error') or status)",
    "",
    "",
    "def apply_athena(sql, database):",
    "    client = boto3.client('athena')",
    "    kwargs = {'QueryString': sql, 'WorkGroup': ATHENA_WORKGROUP}",
    "    if database:",
    "        kwargs['QueryExecutionContext'] = {'Database': database}",
    "    execution = client.start_query_execution(**kwargs)",
    "    execution_id = execution['QueryExecutionId']",
    "    while True:",
    "        desc = client.get_query_execution(QueryExecutionId=execution_id)",
    "        status = desc['QueryExecution']['Status']",
    "        state = status['State']",
    "        if state in ('SUCCEEDED', 'FAILED', 'CANCELLED'):",
    "            break",
    "        time.sleep(2)",
    "    if state != 'SUCCEEDED':",
    "        raise RuntimeError(status.get('StateChangeReason') or state)",
    "",
    "",
    "def main():",
    "    plan = json.loads(fetch_text(SCRIPTS_BUCKET, PLAN_KEY))",
    "    phases = plan.get('phases', {})",
    "    if PHASE not in phases:",
    "        raise ValueError(f'Unknown phase {PHASE}')",
    "    applied = 0",
    "    file_count = 0",
    "    for entry in phases[PHASE]:",
    "        path = entry['path']",
    "        text = fetch_text(SCRIPTS_BUCKET, path)",
    "        if LAKE_BUCKET and '${LakeBucket}' in text:",
    "            text = text.replace('${LakeBucket}', LAKE_BUCKET)",
    "        if STAGING_BUCKET and '${StagingBucket}' in text:",
    "            text = text.replace('${StagingBucket}', STAGING_BUCKET)",
    "        statements = split_statements(text)",
    "        file_count += 1",
    "        for number, sql in enumerate(statements, start=1):",
    "            try:",
    "                if TARGET == 'redshift-serverless':",
    "                    apply_redshift(sql)",
    "                elif TARGET == 'athena-iceberg':",
    "                    apply_athena(sql, entry.get('database'))",
    "                else:",
    "                    raise ValueError(f'Unknown target {TARGET}')",
    "            except Exception as error:",
    "                message = f'{path} statement {number}: {error}'",
    "                if entry.get('continue_on_error'):",
    "                    print(f'WARN {message}')",
    "                else:",
    "                    raise RuntimeError(message) from error",
    "            applied += 1",
    "    print(f'Applied {applied} statements from {file_count} files in phase {PHASE}.')",
    "",
    "",
    "if __name__ == '__main__':",
    "    main()",
    "",
  ].join("\n");
}
